pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 blockOffset) public {
        // Roll the chain so the guess target block is a fresh, fuzzer-chosen block.
        uint256 n = bound(blockOffset, 1, type(uint24).max);
        vm.roll(n);

        address actor = address(0xA11CE);
        vm.deal(actor, 2 ether);

        // Lock in a guess; contract records target = block.number + 1 = n + 1.
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(uint256(12345)));

        // Move past the target block so settle() is admissible; blockhash(n+1)
        // is now resolvable and identical for the test and the contract.
        vm.roll(n + 2);
        bytes32 answer = keccak256(abi.encodePacked(blockhash(n + 1)));

        // Corrective re-lock is impossible (block != 0), so instead verify via a
        // fresh identical scenario: the actor's locked guess equals `answer` iff
        // the contract stored it verbatim. Deploy a second actor to lock the answer.
        address winner = address(0xB0B);
        vm.deal(winner, 2 ether);
        // Cannot lock on same contract twice with a new target; instead use the
        // rule on the settled outcome: since actor's stored guess was bytes32(uint256(12345))
        // verbatim in the reference contract, we can always pick the fuzzed block's
        // answer to match by re-running the whole flow with h = answer precomputed.
        // To keep the flow self-contained, use a fresh contract instance per fuzz run.
        C c2 = new C{value: 1 ether}();
        vm.roll(n);
        vm.prank(winner);
        c2.lockInGuess{value: 1 ether}(answer);
        vm.roll(n + 2);

        uint256 balBefore = winner.balance;
        vm.prank(winner);
        c2.settle();

        // Universal rule: locking in the exact answer hash and settling must pay 2 ether.
        assertTrue(winner.balance == balBefore + 2 ether);
    }
}

