pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(address actor, uint256 rollSeed) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.deal(actor, 1 ether);

        // lock in a guess at the current block; target block is block.number + 1
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(bytes32(0));

        // move past the target block so settle() is admissible
        vm.roll(block.number + 1 + bound(rollSeed, 1, 10));

        // compute the winning answer exactly as settle() does
        bytes32 ans = keccak256(abi.encodePacked(blockhash(block.number - 1 - (block.number - 1 - block.number))));
        // recompute properly: the recorded target block is the block after lockInGuess's block.
        // We roll to target+delta, so recompute from a fresh lock if needed — instead simply settle
        // with the answer derived from the target blockhash observed by the test.
        // The test environment and the contract observe the same blockhash for the target block.
        bytes32 winningHash = keccak256(abi.encodePacked(blockhash(block.number - bound(rollSeed, 1, 10))));

        vm.prank(actor);
        c.settle();

        // General rule: if the stored guess equals the answer, settle pays out 2 ether,
        // so c retains only its initial 1 ether. The mutant never stores the guess
        // (guess stays bytes32(0)), never matches a nonzero answer, and keeps 2 ether.
        assertTrue(address(c).balance == 1 ether);
    }
}

